package com.inventra.backend.security;
import com.inventra.backend.model.User; import com.inventra.backend.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.AuthorityUtils; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt;private final UserRepository users;public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String t=h.substring(7);if(jwt.isTokenValid(t)&&SecurityContextHolder.getContext().getAuthentication()==null){String email=jwt.extractEmail(t);User u=users.findByEmailIgnoreCase(email).orElse(null);if(u!=null&&u.isActive())SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getEmail(),null,AuthorityUtils.NO_AUTHORITIES));}}catch(Exception ignored){}}chain.doFilter(req,res);}}
